"""Camera-guided controller for the single service episode. Commands are recorded in history.py."""
import sys,json,time,traceback,os
import numpy as np
from scipy.spatial import cKDTree
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot();spec=r.spec();cams=list(spec['cameras']);counter=0

def cloud(o,c):
 d=o.depth[c].astype(float).squeeze();K=np.array(o.meta['cameras'][c]['intrinsic_cv']);T=np.array(o.meta['cameras'][c]['cam2world_gl']);v,u=np.indices(d.shape)
 p=np.stack([(u-K[0,2])*d/K[0,0],-(v-K[1,2])*d/K[1,1],-d],-1)@T[:3,:3].T+T[:3,3]
 return p

def save(o,label='obs'):
 global counter
 counter+=1;path=f'/app/output/runs/{counter:03d}_{label}';o.save(path)
 for c in cams:
  if c in o.last:Image.fromarray(o.last[c]).save('/app/output/'+c+'.png')
 print(path, o.meta.get('task'),flush=True)
 return o

def observe():return save(r.get_obs(cameras=cams,include_depth=True))

def move(q,seconds=1.,label='move'):
 global o
 q=np.asarray(q);n=max(1,round(seconds*60));start=np.array(o.meta['proprio']['now'][58:87]);A=start+(q-start)*np.linspace(1/n,1,n)[:,None]
 o=save(r.submit('joint_position',A,dt=1/60,cameras=cams,include_depth=True,video='frames',video_fps=5,note=label),label)
 return o

def joints():return np.array(o.meta['proprio']['now'][:29])
def targets():return np.array(o.meta['proprio']['now'][58:87])
def handcloud(o):
 pts=[]
 for c in ['front','top','oblique']:
  p=cloud(o,c);im=o.last[c].astype(float)
  mask=(p[:,:,2]>.69)&(p[:,:,2]<.85)&(p[:,:,0]>-.16)&(p[:,:,0]<.16)&(p[:,:,1]>-.1)&(p[:,:,1]<.25)&(im.min(2)>100)&(im.max(2)-im.min(2)<65)
  pts.append(p[mask])
 return np.concatenate(pts)

def icp(src,dst):
 T=np.eye(4);tree=cKDTree(dst)
 for i in range(35):
  pp=src@T[:3,:3].T+T[:3,3];d,idx=tree.query(pp);keep=d<.025
  a=pp[keep];b=dst[idx[keep]];ac=a.mean(0);bc=b.mean(0);u,s,vt=np.linalg.svd((a-ac).T@(b-bc));rot=vt.T@u.T
  if np.linalg.det(rot)<0:vt[-1]*=-1;rot=vt.T@u.T
  tt=bc-rot@ac;T[:3,3]=rot@T[:3,3]+tt;T[:3,:3]=rot@T[:3,:3]
 return T,float(np.mean(d[keep]))

o=observe();qinit=joints();hinit=handcloud(o);np.save('/app/output/hinit.npy',hinit)
while True:
 if os.path.exists('/app/output/command.py'):
  code=open('/app/output/command.py').read();os.remove('/app/output/command.py')
  with open('/app/output/history.py','a') as f:f.write('\n'+code+'\n')
  try:exec(compile(code,'command.py','exec'),globals())
  except Exception:traceback.print_exc()
  open('/app/output/ready','w').write(str(time.time()))
 time.sleep(.1)
PY
